// Simulation-only behavioral compatibility models for the Xilinx FP wrappers
// generated by legup_vivado_flow.sh. They reproduce the configured throughput
// and fixed result latency; they are not synthesizable IP replacements.
module legup_fp_binary #(parameter LATENCY = 8, parameter OP = 0) (
  input wire aclk, input wire aclken, input wire s_axis_a_tvalid,
  input wire [31:0] s_axis_a_tdata, input wire s_axis_b_tvalid,
  input wire [31:0] s_axis_b_tdata, output wire m_axis_result_tvalid,
  output wire [31:0] m_axis_result_tdata
);
  reg [31:0] data [0:LATENCY-1]; reg valid [0:LATENCY-1]; integer i;
  shortreal a, b, r;
  always @(posedge aclk) if (aclken) begin
    a = $bitstoshortreal(s_axis_a_tdata); b = $bitstoshortreal(s_axis_b_tdata);
    if (OP == 0) r = a + b; else if (OP == 1) r = a - b; else if (OP == 2) r = a * b; else r = a / b;
    data[0] <= $shortrealtobits(r); valid[0] <= s_axis_a_tvalid && s_axis_b_tvalid;
    for (i = 1; i < LATENCY; i = i + 1) begin data[i] <= data[i-1]; valid[i] <= valid[i-1]; end
  end
  assign m_axis_result_tdata = data[LATENCY-1]; assign m_axis_result_tvalid = valid[LATENCY-1];
endmodule

module addf_vitis_hls_single_precision_lat_8(input wire aclk, aclken, s_axis_a_tvalid, input wire [31:0] s_axis_a_tdata, input wire s_axis_b_tvalid, input wire [31:0] s_axis_b_tdata, output wire m_axis_result_tvalid, output wire [31:0] m_axis_result_tdata);
  legup_fp_binary #(.LATENCY(8), .OP(0)) model(.*);
endmodule
module subf_vitis_hls_single_precision_lat_8(input wire aclk, aclken, s_axis_a_tvalid, input wire [31:0] s_axis_a_tdata, input wire s_axis_b_tvalid, input wire [31:0] s_axis_b_tdata, output wire m_axis_result_tvalid, output wire [31:0] m_axis_result_tdata);
  legup_fp_binary #(.LATENCY(8), .OP(1)) model(.*);
endmodule
module mulf_vitis_hls_single_precision_lat_4(input wire aclk, aclken, s_axis_a_tvalid, input wire [31:0] s_axis_a_tdata, input wire s_axis_b_tvalid, input wire [31:0] s_axis_b_tdata, output wire m_axis_result_tvalid, output wire [31:0] m_axis_result_tdata);
  legup_fp_binary #(.LATENCY(4), .OP(2)) model(.*);
endmodule
module divf_vitis_hls_single_precision_lat_28(input wire aclk, aclken, s_axis_a_tvalid, input wire [31:0] s_axis_a_tdata, input wire s_axis_b_tvalid, input wire [31:0] s_axis_b_tdata, output wire m_axis_result_tvalid, output wire [31:0] m_axis_result_tdata);
  legup_fp_binary #(.LATENCY(28), .OP(3)) model(.*);
endmodule

module legup_sitofp_7(input wire aclk, aclken, s_axis_a_tvalid, input wire [31:0] s_axis_a_tdata, output wire s_axis_a_tready, output wire m_axis_result_tvalid, input wire m_axis_result_tready, output wire [31:0] m_axis_result_tdata);
  reg [31:0] data [0:6]; reg valid [0:6]; integer i; shortreal r;
  always @(posedge aclk) if (aclken) begin
    r = $itor($signed(s_axis_a_tdata)); data[0] <= $shortrealtobits(r); valid[0] <= s_axis_a_tvalid;
    for (i = 1; i < 7; i = i + 1) begin data[i] <= data[i-1]; valid[i] <= valid[i-1]; end
  end
  assign s_axis_a_tready = 1'b1; assign m_axis_result_tdata = data[6]; assign m_axis_result_tvalid = valid[6];
endmodule
